import React from 'react';
import styles from '../pages/Jobs.module.css';

interface JobPaginationProps {
    currentPage: number;
    totalPages: number;
}

export const JobPagination: React.FC<JobPaginationProps> = ({ currentPage, totalPages }) => {
    return (
        <div className={styles.pagination}>
            <div>Page {currentPage} of {totalPages}</div>

            <div className={styles.pageControls}>
                <button className={`${styles.pageBtn} ${currentPage === 1 ? styles.pageBtnDisabled : ''}`}>
                    &lt; Previous
                </button>
                <button className={`${styles.pageBtn} ${styles.pageBtnActive}`}>1</button>
                <button className={styles.pageBtn}>2</button>
                <button className={styles.pageBtn}>3</button>
                <button className={styles.pageBtn}>4</button>
                <span style={{ padding: '0 4px', color: '#94A3B8' }}>...</span>
                <button className={styles.pageBtn}>7</button>
                <button className={styles.pageBtn}>8</button>
                <button className={styles.pageBtn}>9</button>
                <button className={styles.pageBtn}>10</button>
                <button className={styles.pageBtn}>
                    Next &gt;
                </button>
            </div>

            <div className={styles.rowsControl}>
                <span>Go to</span>
                <input type="text" placeholder="Page" style={{ width: '48px', padding: '6px', border: '1px solid #E2E8F0', borderRadius: '6px', textAlign: 'center' }} />
                <select defaultValue="10">
                    <option value="10">10 / page</option>
                    <option value="20">20 / page</option>
                    <option value="50">50 / page</option>
                </select>
            </div>
        </div>
    );
};
